DIRS = {1: (0, -3), 2: (0, 3), 3: (-3, 0), 4: (3, 0)}

def _icons(board):
    icons = []
    for y in range(1, 63):
        for x in range(1, 63):
            c = board[y][x]
            if c not in (9, 11):
                continue
            good = True
            for dy in (-1, 0, 1):
                for dx in (-1, 0, 1):
                    want = c if dx == 0 and dy == 0 else 4
                    if board[y + dy][x + dx] != want:
                        good = False
            if good:
                icons.append((x, y, c))
    return icons

def _head(board):
    for y in range(64):
        for x in range(64):
            if board[y][x] == 0:
                return x, y
    return None

def _bend(board, color):
    for y in range(64):
        for x in range(64):
            if board[y][x] != color:
                continue
            horizontal = any(0 <= x + d < 64 and board[y][x + d] == color
                             for d in (-1, 1))
            vertical = any(0 <= y + d < 64 and board[y + d][x] == color
                           for d in (-1, 1))
            if horizontal and vertical:
                return x, y
    return None

def _cross(board, color, head):
    x, y = head
    cells = {head}
    for xx in range(64):
        if board[y][xx] == color:
            cells.add((xx, y))
    for yy in range(64):
        if board[yy][x] == color:
            cells.add((x, yy))
    return cells

def _covered(state):
    for x, y, color in state["icons"]:
        cells = state["shapes"].get(color, set())
        if not any((xx, yy) in cells
                   for xx in range(x - 1, x + 2)
                   for yy in range(y - 1, y + 2)):
            return False
    return True

def init(board):
    h = _head(board)
    active = None
    if h is not None:
        x, y = h
        for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
            xx, yy = x + dx, y + dy
            if 0 <= xx < 64 and 0 <= yy < 64 and board[yy][xx] in (9, 11):
                active = board[yy][xx]
                break
    shapes, heads = {}, {}
    for color in (9, 11):
        bend = h if color == active else _bend(board, color)
        if bend is not None:
            heads[color] = bend
            shapes[color] = _cross(board, color, bend)
    state = {
        "orig": [r[:] for r in board],
        "icons": _icons(board),
        "shapes": shapes,
        "heads": heads,
        "active": active,
        "moves": {9: 0, 11: 0},
        "energy": 0,
        "won": False,
        "over": False,
    }
    state["won"] = _covered(state)
    return state

def render(state):
    b = [r[:] for r in state["orig"]]
    for color in (9, 11):
        for x, y in state["shapes"].get(color, ()):
            b[y][x] = color
    for x, y, color in state["icons"]:
        for dy in (-1, 0, 1):
            for dx in (-1, 0, 1):
                b[y + dy][x + dx] = color if dx == 0 and dy == 0 else 4
    if state["active"] in state["heads"] and not state["won"]:
        x, y = state["heads"][state["active"]]
        b[y][x] = 0
    b[63] = [15] * min(64, state["energy"]) + [1] * max(0, 64 - state["energy"])
    return b

def key(state):
    return (state["active"], state["energy"], state["won"], state["over"],
            tuple(sorted(state["moves"].items())),
            tuple((c, tuple(sorted(state["shapes"].get(c, ()))))
                  for c in (9, 11)))

def step(state, action):
    s = {
        "orig": state["orig"],
        "icons": state["icons"],
        "shapes": {c: set(v) for c, v in state["shapes"].items()},
        "heads": dict(state["heads"]),
        "active": state["active"],
        "moves": dict(state["moves"]),
        "energy": state["energy"],
        "won": state["won"],
        "over": state["over"],
    }
    if s["won"] or s["over"]:
        return s
    a = action[0]
    c = s["active"]
    if c not in (9, 11):
        return s
    s["energy"] += 1

    if a == 5:
        s["active"] = 11 if c == 9 else 9
    elif a in DIRS:
        s["moves"][c] += 1
        if s["moves"][c] % 3 == 2:
            s["energy"] += 1
        dx, dy = DIRS[a]
        x, y = s["heads"][c]
        old = s["shapes"][c]
        xs = [p[0] for p in old]
        ys = [p[1] for p in old]
        left, right = x - min(xs), max(xs) - x
        up, down = y - min(ys), max(ys) - y
        nx = max(left, min(63 - right, x + dx))
        ny = max(up, min(63 - down, y + dy))
        while (nx, ny) != (x, y) and s["orig"][ny][nx] == 4:
            xx = max(left, min(63 - right, nx + dx))
            yy = max(up, min(63 - down, ny + dy))
            if (xx, yy) == (nx, ny):
                break
            nx, ny = xx, yy
        actual_dx, actual_dy = nx - x, ny - y
        s["shapes"][c] = {(xx + actual_dx, yy + actual_dy) for xx, yy in old}
        s["heads"][c] = (nx, ny)
        s["won"] = _covered(s)
    else:
        return s

    if s["energy"] >= 64 and not s["won"]:
        s["energy"] = 64
        s["over"] = True
    return s

def won(state):
    return state["won"]

def lost(state):
    return state["over"]
